  function template() {
    return '<div class="rwm-shell"><div class="rwm-head"><span class="rwm-brand">📡</span><h2>Trail Mesh</h2><span id="rwmStatus" class="rwm-badge">Stopped</span><button class="rwm-close" data-rwm-close aria-label="Close Trail Mesh">✕</button></div>' +
      '<div class="rwm-tabs">' + ['Connect','Chat','Team','SOS','Share','Fun','Guide'].map(function (x, i) { return '<button class="rwm-tab '+(i?'':'active')+'" data-rwm-tab="'+x.toLowerCase()+'">'+x+'</button>'; }).join('') + '</div><div class="rwm-body">' +
      '<section class="rwm-panel active" data-rwm-panel="connect">'+scene('Your offline trail lifeline','Nearby phones · no internet required','🏔️')+'<div class="rwm-card"><h3>Before Trail Mesh starts</h3><p class="rwm-note"><b>RoamWise uses Nearby Devices access (Bluetooth and nearby Wi‑Fi) to discover and communicate with verified RoamWise phones near you.</b> On Android 13 and newer, current Google Nearby uses Nearby/Bluetooth/Wi‑Fi permissions without location. Android 12 (API 31) and older may request location for discovery; RoamWise does not store or upload that compatibility permission. Your chosen trail name is visible nearby and text and alerts transfer device-to-device. Microphone, precise location and selected-file access occur only when you separately choose a voice note, location-assisted SOS or file share.</p><p class="rwm-note">Internet and mobile service are not required, but devices must remain within local radio range. Trail Mesh is not satellite rescue and does not replace emergency services.</p><input id="rwmName" class="rwm-input" maxlength="32" placeholder="Trail display name"><label class="rwm-note"><input id="rwmEco" type="checkbox" checked> Battery guard: stop automatically after 2 hours (recommended)</label><div class="rwm-row"><button id="rwmStart" class="rwm-btn">Allow & start</button><button id="rwmStop" class="rwm-btn secondary">Stop</button><button id="rwmPing" class="rwm-btn secondary">Test network</button></div><div id="rwmStartError" class="rwm-error" role="alert"></div></div><div class="rwm-card"><h3>Multi-hop relay <span class="rwm-badge rwm-warn">Pro</span></h3><label><input id="rwmRelay" type="checkbox"> Relay text, team, lost-trekker and SOS alerts through verified phones</label><p class="rwm-note">Optional Pro expedition feature. Maximum three hops; duplicate IDs and expiry prevent loops. SOS, lost-trekker, team coordination, local alarm and basic chat remain free for everyone. Files, songs, videos and voice notes are never relayed.</p></div><div class="rwm-card"><h3>Nearby trekkers <span id="rwmPeerCount" class="rwm-badge">0</span></h3><div id="rwmPeers" class="rwm-note">No connected trekkers yet.</div></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="chat"><div class="rwm-card"><h3>Offline Trip Chat & radio room</h3><p class="rwm-note">Messages are shared with verified connected devices and can appear in Trip Chat. Voice is push-to-talk: record, release and share. This remains usable under weak links where live conferencing would break.</p><div id="rwmActivity" class="rwm-activity" aria-live="polite"></div><div id="rwmMessages"></div><textarea id="rwmChatInput" class="rwm-input" rows="2" maxlength="4000" placeholder="Message your nearby team"></textarea><div class="rwm-row"><button id="rwmSend" class="rwm-btn">Send offline</button><button id="rwmVoice" class="rwm-btn secondary">🎙 Record radio note</button><button id="rwmRadioCheck" class="rwm-btn secondary">Radio check</button><button id="rwmClearChat" class="rwm-btn secondary">Clear old chat</button></div><p class="rwm-note rwm-tip">For a call-like exchange, use short radio notes. Continuous full-duplex calling is not promised over a battery-saving mesh radio.</p></div><div class="rwm-card"><h3>Live call readiness <span class="rwm-badge rwm-warn">Native stream</span></h3><p class="rwm-note">A true two-way call needs a native audio stream transport. This bridge intentionally sends small BYTES messages only, so it will not pretend a call is connected or drain a group’s emergency radio. Use radio notes now; the check below explains exactly what is ready for a future 5-minute warning / 30-minute cap call.</p><button id="rwmCallCheck" class="rwm-btn secondary">📞 Check call readiness</button><div id="rwmCallStatus" class="rwm-check wait">○ Call transport not checked</div></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="team"><div class="rwm-card"><h3>Trek leader coordination</h3><input id="rwmCheckpoint" class="rwm-input" maxlength="120" placeholder="Checkpoint or meeting place"><div class="rwm-row"><button class="rwm-btn" data-rwm-team="rollcall">Roll call</button><button class="rwm-btn secondary" data-rwm-team="regroup">Regroup</button><button class="rwm-btn secondary" data-rwm-team="hold">Hold position</button></div></div><div class="rwm-card"><h3>Find a lost trekker</h3><p class="rwm-note">Broadcasts an alert locally. The missing person becomes discoverable only when their phone is running Trail Mesh and enters radio range.</p><input id="rwmLostName" class="rwm-input" maxlength="80" placeholder="Name / description"><button id="rwmLost" class="rwm-btn danger">Broadcast lost-trekker alert</button></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="sos"><div class="rwm-card rwm-sos"><h3>Emergency help</h3><p class="rwm-note">If mobile service exists, contact local emergency services first. Trail Mesh only alerts nearby connected users and delivery is not guaranteed.</p><select id="rwmSosType" class="rwm-input"><option>Medical emergency</option><option>Lost / separated</option><option>Unsafe situation</option><option>Need supplies or assistance</option></select><input id="rwmSosDetails" class="rwm-input" maxlength="240" placeholder="Details, clothing, direction, injury"><label class="rwm-note"><input id="rwmSosLocation" type="checkbox"> Attach precise location (optional; requested only if checked)</label><div class="rwm-row"><button id="rwmSOS" class="rwm-btn danger">Broadcast nearby SOS</button><button id="rwmAlarm" class="rwm-btn secondary">Sound local alarm</button><button id="rwmOfficialSOS" class="rwm-btn secondary">Open RoamWise SOS</button></div></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="share"><div class="rwm-card"><h3>Share without internet</h3><p class="rwm-note">Send selected media directly to a verified teammate. Files above 8 MB show a battery/radio warning; this WebView bridge safely caps a transfer at 64 MB and keeps both screens open until complete.</p><input id="rwmFile" type="file" class="rwm-input" accept="image/*,video/*,audio/*,.pdf,.txt"><button id="rwmShare" class="rwm-btn">Share selected file</button><p class="rwm-note rwm-tip">2–10 GB transfers need a future native FILE-payload stream. They are intentionally not faked here because assembling that much data in a phone WebView can crash the app.</p><div id="rwmTransfers"></div></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="fun">'+scene('Camp mode','Tiny offline games, big trail memories','🔥')+'<div class="rwm-card"><h3>Trail fun</h3><p class="rwm-note">Tap a game to send its challenge. The activity feed confirms whether it was sent, simulated or rejected.</p><div class="rwm-choice"><button class="rwm-btn" data-rwm-fun="photo">📷 Photo challenge</button><button class="rwm-btn secondary" data-rwm-fun="story">🔥 Campfire story</button><button class="rwm-btn secondary" data-rwm-fun="quiz">🧭 Trail quiz</button><button class="rwm-btn secondary" data-rwm-fun="cheer">🙌 Team cheer</button><button class="rwm-btn secondary" data-rwm-fun="scavenger">🍃 Scavenger hunt</button><button class="rwm-btn secondary" data-rwm-fun="summit">🏁 Summit countdown</button></div><div id="rwmFunFeed" class="rwm-test"><div class="rwm-check wait">○ Choose a challenge to begin</div></div></div><div class="rwm-card"><h3>Talk to a trail character</h3><div id="rwmCharacterPortrait" class="rwm-character" aria-live="polite">🧭</div><p class="rwm-note">Ask a locally available travel character for ideas, stories, packing prompts or morale. Replies are an offline RoamWise companion simulation; do not use them for emergency or medical decisions.</p><select id="rwmCharacter" class="rwm-input"><option value="nanda">Nanda · Uttarakhand guide</option><option value="tenzing">Tenzing · Everest storyteller</option><option value="himachali">Maya · Himachal ranger</option><option value="ladakhi">Tashi · Ladakh navigator</option></select><div id="rwmAiMessages" class="rwm-test"><div class="rwm-check wait">○ Choose a character and say hello</div></div><textarea id="rwmAiInput" class="rwm-input" rows="2" maxlength="500" placeholder="Ask about the trail, camp, food or morale"></textarea><div class="rwm-row"><button id="rwmAiSend" class="rwm-btn">Talk offline</button><button id="rwmAiSpeak" class="rwm-btn secondary">🔊 Read last reply</button><button id="rwmAiClear" class="rwm-btn secondary">Clear chat</button></div></div></section>' +
      '<section class="rwm-panel rwm-guide" data-rwm-panel="guide"><div class="rwm-card"><h3>Quick tutorial</h3><ol><li>Open Trail Mesh on every Android phone and tap <b>Allow & start</b>.</li><li>Keep Bluetooth, Wi-Fi and location services enabled. Android may require Nearby Devices and approximate location permissions.</li><li>When a request arrives, open the <b>Nearby radar</b> card. Compare the same verification digits face to face, then tap <b>Accept matching digits</b>. If you missed the popup, the request remains in that card until it expires.</li><li>If you are coordinating by voice, type the digits into <b>Share digits manually</b> to copy/share them. This is a reminder only; it cannot accept a connection or bypass Android verification.</li><li>Use Offline Trip Chat, Team, Share, Fun, or SOS. Keep phones nearby and the app open during transfers.</li><li>Enable relay only when the group agrees; distribute relay phones along the route.</li><li>Tap Stop when the trek ends to stop discovery and advertising.</li></ol></div><div class="rwm-card"><h3>Safety & privacy</h3><ul><li>Your chosen trail name is visible to nearby Trail Mesh users while running.</li><li>Never accept an unexpected verification request.</li><li>Range varies with terrain, bodies, weather, and hardware. Relay is limited to three hops and lightweight alerts.</li><li>Voice uses recorded push-to-talk notes; it is not a guaranteed full-duplex phone call.</li><li>Large files and continuous calls are intentionally limited to preserve battery and emergency radio capacity.</li><li>Trail Mesh cannot silently install an APK on another phone. Use the Play Store or a user-initiated, trusted Android package installer flow and confirm the source before installing.</li><li>Use official emergency channels whenever available. Do not rely on Trail Mesh as your only safety plan.</li></ul></div><div class="rwm-card"><h3>Ailon Tusk shortcuts</h3><p class="rwm-note">Try: “open Trail Mesh”, “mesh status”, “find lost trekker”, or “nearby SOS”. Tusk opens the matching control while you confirm every safety-sensitive broadcast.</p></div></section></div></div>';
  }

  function decoratePanels(root) {
    if(!root.querySelector('[data-rwm-tab="health"]')){var tab=document.createElement('button');tab.className='rwm-tab';tab.dataset.rwmTab='health';tab.textContent='Health';root.querySelector('.rwm-tabs').appendChild(tab);var panel=document.createElement('section');panel.className='rwm-panel';panel.dataset.rwmPanel='health';panel.innerHTML=scene('Trail Mesh health','Live checks, errors and the next recommended action','🩺')+'<div class="rwm-card"><h3>What to do next</h3><div id="rwmNextStep" class="rwm-next"></div><div class="rwm-row" style="margin-top:10px"><button id="rwmHealthRefresh" class="rwm-btn">Run health check</button><button id="rwmCopyLog" class="rwm-btn secondary">Copy report</button><button id="rwmClearLog" class="rwm-btn secondary">Clear</button></div></div><div class="rwm-card"><h3>Permissions · requested only on use</h3><p class="rwm-note">These are the Android capabilities RoamWise can use. Every toggle starts off; the related feature asks at the moment you choose it. Normal network access, vibration and the system file picker do not need runtime consent.</p><div id="rwmPermissionCatalog"></div></div><div class="rwm-card"><h3>Process console</h3><p class="rwm-note">Stored only on this phone. It records Trail Mesh actions and errors, not message contents or selected files.</p><div id="rwmConsole" class="rwm-console"></div></div>';root.querySelector('.rwm-body').appendChild(panel);tab.onclick=function(){selectTab('health');renderConsole();};panel.querySelector('#rwmHealthRefresh').onclick=function(){act('Health check',runSelfTest);};panel.querySelector('#rwmCopyLog').onclick=copyHealthReport;panel.querySelector('#rwmClearLog').onclick=function(){state.logs=[];try{localStorage.removeItem('rw_mesh_health_log');}catch(_){}trace('info','Console','Log cleared');};}
    var art={chat:['Trail radio room','Text and voice notes across the group','💬'],team:['Keep the line together','Roll calls, regrouping and lost-trekker alerts','🧭'],sos:['Help travels outward','Local alarm and verified nearby SOS relay','🆘'],share:['Pass memories phone to phone','Photos, songs and short videos without data','📸'],guide:['Ready before the trail','Practice together while mobile service still works','🥾']};
    Object.keys(art).forEach(function(name){var panel=root.querySelector('[data-rwm-panel="'+name+'"]');if(panel&&!panel.querySelector('.rwm-scene'))panel.insertAdjacentHTML('afterbegin',scene(art[name][0],art[name][1],art[name][2]));});
    var connect=root.querySelector('[data-rwm-panel="connect"]');
    if(connect&&!connect.querySelector('#rwmRadarCard')){var radar=document.createElement('div');radar.className='rwm-card';radar.id='rwmRadarCard';radar.innerHTML='<h3>Nearby radar</h3><p class="rwm-note">The radar shows phones discovered by the local radio scan. A dot is not a verified connection until both people compare the pairing digits and accept.</p><div id="rwmRadar" class="rwm-radar" aria-label="Nearby device radar"></div><div id="rwmRemembered" class="rwm-test"></div><div id="rwmPairings" class="rwm-test"><div class="rwm-check wait">○ No pairing request waiting</div></div><div class="rwm-row"><input id="rwmPairCode" class="rwm-input" inputmode="numeric" maxlength="8" placeholder="Pairing digits to share"><button id="rwmSharePairing" class="rwm-btn secondary">Share digits manually</button></div><p class="rwm-note rwm-tip">Manual sharing sends the digits through your chosen system share sheet or clipboard. It does not bypass the in-person verification step.</p><div class="rwm-check wait"><b>Radio limits:</b> Google Nearby does not expose calibrated RSSI, transmit power or a guaranteed metre range to this WebView. We show unknown instead of inventing a number. Open-air Bluetooth is often roughly 10–30 m and Wi‑Fi peer links can reach farther, but boulders, concrete, vehicles, wet trees, crowds and body blocking can reduce it sharply. Test the exact phones at the trailhead.</div><div class="rwm-check wait"><b>Large groups:</b> P2P_CLUSTER can support a group topology, but 30–100 phones are not a guaranteed single-hop mesh. Use a leader, rear marker and spaced relay volunteers; verify in smaller clusters and keep SOS/short text free of large media.</div>';connect.insertBefore(radar,connect.lastElementChild);radar.querySelector('#rwmSharePairing').onclick=function(){sharePairing();};}
    var guide=root.querySelector('[data-rwm-panel="guide"]');
    if(guide&&!guide.querySelector('#rwmLanguageCard')){guide.insertAdjacentHTML('afterbegin','<div class="rwm-card" id="rwmLanguageCard"><h3>Guide voice & dictation</h3><p class="rwm-note">Choose a language for offline character and guide playback. Dictation requests the microphone only when you tap the button; if Android WebView does not expose speech recognition, type the question instead.</p><div class="rwm-row"><select id="rwmLanguage" class="rwm-input" aria-label="Guide language"></select><button id="rwmGuideDictate" class="rwm-btn secondary">🎙 Dictate question</button></div><div id="rwmDictationStatus" class="rwm-check wait">○ Dictation is off</div></div>');var lang=document.getElementById('rwmLanguage');if(lang){lang.innerHTML=Object.keys(SUPPORTED_LANGUAGES).map(function(k){return '<option value="'+esc(k)+'">'+esc(SUPPORTED_LANGUAGES[k])+'</option>';}).join('');lang.value=selectedLanguage();lang.onchange=function(){localStorage.setItem('rw_mesh_language',lang.value);trace('ok','Guide language','Playback language set to '+lang.value);};}var dictate=document.getElementById('rwmGuideDictate');if(dictate)dictate.onclick=function(){act('Guide dictation',toggleDictation);};}
    if(guide&&!guide.querySelector('#rwmAreaGuide'))guide.insertAdjacentHTML('beforeend','<div class="rwm-card" id="rwmAreaGuide"><div class="rwm-guide-orb" aria-hidden="true">🧭</div><h3>AI trail guide · area check</h3><p class="rwm-note">Ask an offline RoamWise guide for a practical next step. On your request it reads this phone’s location (if allowed), nearby verified peers, battery level and connectivity. It does not continuously track you or replace a local guide, map, weather alert or emergency service.</p><textarea id="rwmGuideQuestion" class="rwm-input" rows="2" maxlength="400" placeholder="Ask: should we regroup, rest, turn back, or prepare for weather?"></textarea><div class="rwm-row"><button id="rwmGuideScan" class="rwm-btn">Scan area & ask guide</button><button id="rwmGuideClear" class="rwm-btn secondary">Clear advice</button></div><div id="rwmGuideAnswer" class="rwm-test"><div class="rwm-check wait">○ The guide is ready when you are</div></div></div>');
    if(guide&&!guide.querySelector('#rwmFeatureGuide'))guide.insertAdjacentHTML('beforeend','<div class="rwm-card" id="rwmFeatureGuide"><h3>Feature-by-feature field guide</h3><p class="rwm-note rwm-tip"><b>Connect:</b> Start on every phone before departure, compare verification digits face to face, then run the teammate test with airplane mode on and Bluetooth/Wi-Fi re-enabled.</p><p class="rwm-note rwm-tip"><b>Chat:</b> Use text for fast updates and short voice notes when gloves or darkness make typing difficult. Messages need at least one verified peer.</p><p class="rwm-note rwm-tip"><b>Team:</b> Set a checkpoint, run roll calls at junctions, and use Hold position before searching for a missing person.</p><p class="rwm-note rwm-tip"><b>SOS:</b> Describe injury, clothing and direction; tick Attach precise location only when you consciously want Android to request it. Sound the alarm to help nearby searchers, but call emergency services whenever possible.</p><p class="rwm-note rwm-tip"><b>Share:</b> Select a file up to 64 MB and keep both screens open until complete. Files above 8 MB show a confirmation warning; prefer compressed media to preserve battery and radio capacity.</p><p class="rwm-note rwm-tip"><b>Fun:</b> Start a tiny challenge for the group. Activities send only text; use Share separately for the winning photo or song.</p><p class="rwm-note rwm-tip"><b>Travel characters:</b> Choose a local character in Fun, ask a short question, and use Read last reply for offline voice playback. Treat replies as entertainment and planning prompts—not a substitute for a guide, map, weather report, or emergency service.</p><p class="rwm-note rwm-tip"><b>Battery:</b> Keep the two-hour guard on for casual use. Turn it off only for a planned long session, and stop Trail Mesh at camp or journey end.</p></div><div class="rwm-card" id="rwmMountainContext"><h3>Why this matters in the mountains</h3><p class="rwm-note">Mountain travel can move from connected to isolated within one bend. Deep valleys, forest, rock, snow, weather and crowds can weaken both mobile coverage and local radio range. Trail Mesh gives a prepared group a short-range coordination layer while their phones can still reach one another.</p><p class="rwm-note rwm-tip"><b>Uttarakhand:</b> On pilgrim routes, forest approaches and treks around places such as Kedarkantha, Valley of Flowers or the approaches to high-altitude camps, a group may stretch between switchbacks or separate at tea stops. Use named checkpoints, junction roll calls and Hold position before anyone turns back to search.</p><p class="rwm-note rwm-tip"><b>Himachal Pradesh:</b> On wooded trails, ridge crossings and busy routes around Manali, Parvati Valley, Dharamshala and Spiti approaches, use offline chat for pace changes, water breaks and vehicle rendezvous. Place willing relay phones between the leader and rear marker instead of clustering every phone together.</p><p class="rwm-note rwm-tip"><b>Everest region:</b> International roaming and lodge Wi-Fi may be intermittent, and terrain can block radio line-of-sight. Prepare names and test at the trailhead; use Trail Mesh only for companions within local phone-radio range. For high-altitude expeditions, carry appropriate satellite communication, trained guides and an established rescue plan.</p><p class="rwm-note rwm-tip"><b>Ladakh and other remote regions:</b> Long road gaps, sparse coverage and widely separated viewpoints make a pre-agreed regroup point valuable. Use concise text, avoid large media during an incident, preserve power, and keep a rear marker with the slower members.</p><p class="rwm-note"><b>A useful pattern:</b> leader at the front, a designated rear marker, relay volunteers spaced through the group, and a fixed checkpoint/time everyone understands before moving. A forwarded alert proves only that another phone relayed it—not that rescuers received it.</p></div><div class="rwm-card"><h3>A trailhead story</h3><p class="rwm-note">Imagine twelve trekkers leaving before sunrise. The leader reaches a fork while mist hides the rear group; two people stop to help with a loose boot, and mobile service disappears. Because the team paired Trail Mesh before departure, the rear marker sends “delayed 10 minutes,” the middle relay forwards it, and the leader replies “holding at the marked bridge.” Nobody guesses which path to take. That small moment—prepared names, verified phones and one clear checkpoint—is the job Trail Mesh is designed to support.</p></div>');
    renderPermissionCatalog();
    var scan=document.getElementById('rwmGuideScan');if(scan&&!scan.dataset.bound){scan.dataset.bound='1';scan.onclick=function(){act('AI area guide',areaGuideScan);};}
    var clearGuide=document.getElementById('rwmGuideClear');if(clearGuide&&!clearGuide.dataset.bound){clearGuide.dataset.bound='1';clearGuide.onclick=function(){var out=document.getElementById('rwmGuideAnswer');if(out)out.innerHTML='<div class="rwm-check wait">○ The guide is ready when you are</div>';trace('info','AI area guide','Advice cleared');};}
  }

  function renderPermissionCatalog(){var box=document.getElementById('rwmPermissionCatalog');if(!box)return;var rows=[['Nearby radios','Bluetooth scan/connect/advertise + Nearby Wi‑Fi','Connect → Allow & start','Required only while Trail Mesh runs'],['Legacy location','Android 12 (API 31) and older Nearby compatibility','Connect → Allow & start on legacy devices','Android 12L/API 32 and newer do not request location for Nearby'],['Precise location','High-accuracy location-assisted SOS','SOS → tick Attach precise location','Requested only when the SOS flow uses the location'],['Microphone','Push-to-talk voice notes','Chat → Record radio note','Requested only when recording starts'],['Camera','Optional photo capture','Fun/Share → choose a camera action','Not requested by Trail Mesh; the system picker can be used'],['Notifications','Optional status/emergency notifications','Only when an opt-in notification feature is enabled','Off by default'],['Files and media','Selected file transfer','Share → Choose file','Uses the system picker; no broad storage permission'],['Network and vibration','Online fallback and local alarm','Feature-specific use','Normal capabilities; no runtime prompt']];box.innerHTML=rows.map(function(r){return '<div class="rwm-check wait"><input type="checkbox" disabled aria-label="'+esc(r[0])+' permission toggle"> <span><b>'+esc(r[0])+'</b><br>'+esc(r[1])+'<br><small>'+esc(r[2])+' · '+esc(r[3])+'</small></span></div>';}).join('');}
  function renderRadar(){var radar=document.getElementById('rwmRadar');if(!radar)return;var peers=Object.keys(state.peers);radar.innerHTML=peers.map(function(key,index){var angle=(index*137.5)%360, radius=22+(index%3)*17, x=50+Math.cos(angle*Math.PI/180)*radius, y=50+Math.sin(angle*Math.PI/180)*radius;return '<span class="rwm-dot" title="'+esc(state.peers[key].name||'Nearby trekker')+'" style="left:'+x+'%;top:'+y+'%"></span>';}).join('');}
  function renderPairings(){var box=document.getElementById('rwmPairings');if(!box)return;Object.keys(state.pendingPairings).forEach(function(key){if(state.pendingPairings[key].expiresAt&&state.pendingPairings[key].expiresAt<=Date.now())delete state.pendingPairings[key];});var keys=Object.keys(state.pendingPairings);if(!keys.length){box.innerHTML='<div class="rwm-check wait">○ No pairing request waiting</div>';return;}box.innerHTML=keys.map(function(key){var p=state.pendingPairings[key];return '<div class="rwm-card"><b>Pair with '+esc(p.name||'Nearby trekker')+'</b><p class="rwm-note">Compare these digits in person on both phones:</p><div style="font-size:28px;letter-spacing:.25em;color:var(--gold,#E8BA6C)">'+esc(p.code||'Unavailable')+'</div><div class="rwm-row"><button class="rwm-btn" data-rwm-accept="'+esc(key)+'">Accept matching digits</button><button class="rwm-btn secondary" data-rwm-reject="'+esc(key)+'">Reject</button></div></div>';}).join('');box.querySelectorAll('[data-rwm-accept]').forEach(function(b){b.onclick=function(){acceptPairing(b.dataset.rwmAccept);};});box.querySelectorAll('[data-rwm-reject]').forEach(function(b){b.onclick=function(){rejectPairing(b.dataset.rwmReject);};});}
  function renderTransfers(){var box=document.getElementById('rwmTransfers');if(!box)return;Object.keys(state.received).forEach(function(key){var f=state.received[key],item=document.getElementById('rwmTransfer-'+key);if(!item){item=document.createElement('div');item.id='rwmTransfer-'+key;item.className='rwm-card';box.prepend(item);}var preview=/^image\//.test(f.mime)?'<img class="rwm-media-preview" src="'+f.url+'" alt="Received '+esc(f.name)+'">':/^video\//.test(f.mime)?'<video class="rwm-media-preview" controls preload="metadata" src="'+f.url+'"></video>':/^audio\//.test(f.mime)?'<audio class="rwm-media-preview" controls preload="metadata" src="'+f.url+'"></audio>':'';item.innerHTML='<div>Received '+esc(f.name)+' · '+formatBytes(f.size)+'</div>'+preview+'<div class="rwm-progress"><i style="width:100%"></i></div><div class="rwm-row"><button class="rwm-btn" data-rwm-open="'+esc(key)+'">Open</button><a class="rwm-btn secondary" data-rwm-save="'+esc(key)+'" href="'+f.url+'" download="'+esc(f.name)+'">Save</a></div>';item.querySelector('[data-rwm-open]').onclick=function(){openBlob(f.url);};});}
  function acceptPairing(endpointId){var p=state.pendingPairings[endpointId];if(!p)return;try{requirePlugin().acceptConnection({endpointId:endpointId}).then(function(){delete state.pendingPairings[endpointId];trace('ok','Pairing','Accepted '+(p.name||'nearby trekker'));render();}).catch(function(e){trace('error','Pairing',e.message||'Could not accept pairing');toast(e.message||'Could not accept pairing');});}catch(e){trace('error','Pairing',e.message||'Could not accept pairing');toast(e.message||'Could not accept pairing');}}
  function rejectPairing(endpointId){var p=state.pendingPairings[endpointId];delete state.pendingPairings[endpointId];renderPairings();if(plugin())plugin().rejectConnection({endpointId:endpointId}).catch(function(){});trace('info','Pairing','Rejected '+((p&&p.name)||'nearby trekker'));}
  function sharePairing(){var input=document.getElementById('rwmPairCode'),code=(input&&input.value||'').replace(/\D/g,'');if(!/^\d{4,8}$/.test(code)){toast('Enter the pairing digits shown on both phones');return;}var text='RoamWise Trail Mesh pairing digits: '+code+'\nCompare in person before accepting. These digits do not install the app or bypass verification.';if(navigator.share){navigator.share({title:'RoamWise pairing digits',text:text}).then(function(){trace('ok','Pairing','Digits shared manually');}).catch(function(){});}else if(navigator.clipboard){navigator.clipboard.writeText(text).then(function(){toast('Pairing digits copied');trace('ok','Pairing','Digits copied manually');}).catch(function(){toast(text);});}else toast(text);}
  function renderConsole(){var next=document.getElementById('rwmNextStep'),box=document.getElementById('rwmConsole');if(next)next.textContent=nextStep();if(box)box.innerHTML=state.logs.slice().reverse().map(function(x){return '<div class="rwm-log '+esc(x.level)+'"><b>'+esc(x.at)+' · '+esc(x.step)+'</b><br>'+esc(x.message)+'</div>';}).join('')||'<div class="rwm-log">No events yet. Run the health check.</div>';renderPermissionCatalog();}
