    var peers = document.getElementById('rwmPeers'); if (peers) { var list = Object.keys(state.peers).map(function (key) { var p = state.peers[key]; return '<div class="rwm-msg"><b>'+esc(p.name || 'Nearby trekker')+'</b><div class="rwm-meta">'+esc(p.connected ? 'Connected and verified' : p.found ? 'Discovered' : 'Disconnected')+' · '+esc(peerType(p))+' · '+esc(peerDistance(p))+'</div></div>'; }); peers.innerHTML = list.join('') || 'No connected trekkers yet.'; }
    var messages = document.getElementById('rwmMessages'); if (messages) { messages.innerHTML = state.messages.slice(-100).map(function (m) { var audio=m.audioUrl?'<audio class="rwm-media-preview" controls preload="metadata" src="'+esc(m.audioUrl)+'"></audio>':''; return '<div class="rwm-msg '+(m.mine?'mine':'')+'"><b>'+esc(m.from)+'</b> '+esc(m.text||'')+audio+'<div class="rwm-meta">'+esc(m.time)+'</div></div>'; }).join('') || '<p class="rwm-note">No offline messages yet.</p>'; messages.scrollTop = messages.scrollHeight; }
    var funFeed=document.getElementById('rwmFunFeed');if(funFeed)funFeed.innerHTML=state.funEvents.slice(-8).reverse().map(function(e){return '<div class="rwm-check '+(e.ok?'pass':'fail')+'">'+(e.ok?'✓ ':'✕ ')+esc(e.text)+' <span class="rwm-meta">'+esc(e.time)+'</span></div>';}).join('')||'<div class="rwm-check wait">○ Choose a challenge to begin</div>';
    var aiFeed=document.getElementById('rwmAiMessages');if(aiFeed)aiFeed.innerHTML=state.aiMessages.slice(-12).map(function(m){return '<div class="rwm-msg '+(m.mine?'mine':'')+'"><b>'+esc(m.from)+'</b> '+esc(m.text)+'<div class="rwm-meta">'+esc(m.time)+'</div></div>';}).join('')||'<div class="rwm-check wait">○ Choose a character and say hello</div>';
    renderRadar();
