  function renderActivity(){var box=document.getElementById('rwmActivity');if(!box)return;var rows=Object.keys(state.activity).filter(function(k){var x=state.activity[k];return !x.expiresAt||x.expiresAt>Date.now();}).map(function(k){return '<span class="rwm-activity-item">'+esc(state.activity[k].text)+'</span>';});box.innerHTML=rows.join('')||'';box.classList.toggle('show',rows.length>0);if(rows.length)setTimeout(renderActivity,1100);}
