  async function start() { trace('info','Start','Checking Android permissions and radios');state.sessionRequested=true;try{stopDemo(false);showStartError('');var button=document.getElementById('rwmStart');button.disabled=true;button.textContent='Starting radios…';var name=document.getElementById('rwmName').value.trim()||safeName();localStorage.setItem('rw_mesh_name',name);await requirePlugin().requestMeshPermissions();trace('ok','Permissions','Required grants are available');await requirePlugin().start({displayName:name});state.running=true;if(state.ecoTimer)clearTimeout(state.ecoTimer);if(document.getElementById('rwmEco').checked)state.ecoTimer=setTimeout(function(){stop();toast('Trail Mesh stopped by the 2-hour battery guard');},7200000);trace('ok','Start','Advertising and discovery started');render();cue('success');toast('Trail Mesh is running nearby');}catch(e){state.sessionRequested=false;var raw=e.message||'Could not start Trail Mesh',msg=raw;if(/8034|MISSING_PERMISSION_ACCESS_COARSE_LOCATION/i.test(raw))msg='Google Nearby rejected the legacy location check. On Android 12 or older, allow the requested location permission. On Android 13+, install the latest build so only Nearby/Bluetooth/Wi-Fi are required.';else if(/8032|MISSING_PERMISSION_ACCESS_WIFI_STATE/i.test(raw))msg='This build is missing Android’s normal ACCESS_WIFI_STATE capability required by Google Nearby. Install the latest build; no extra permission prompt is needed.';state.startError=raw;trace('error','Start',raw);showStartError(msg);cue('alert');}finally{var b=document.getElementById('rwmStart');if(b){b.disabled=false;b.textContent='Allow & start';}renderConsole();} }
