  function speakCharacterReply(){var reply=state.aiMessages.slice().reverse().find(function(m){return !m.mine;});if(!reply)throw new Error('Ask your trail character a question first');var lang=selectedLanguage(),tts=window.Capacitor&&window.Capacitor.Plugins&&window.Capacitor.Plugins.TextToSpeech;if(tts&&typeof tts.speak==='function'){return Promise.resolve(tts.speak({text:reply.text,lang:lang,rate:.94,pitch:1.03,volume:1,queueStrategy:0})).then(function(){trace('ok','Trail character','Native voice playback started in '+lang);cue('success');}).catch(function(){trace('warn','Trail character','Native voice unavailable for '+lang+'; trying browser voice');speakLastCharacter();});}speakLastCharacter();}
