  function installLifecycleGuard(){if(window.__rwMeshLifecycleGuard)return;window.__rwMeshLifecycleGuard=true;document.addEventListener('visibilitychange',function(){if(document.visibilityState==='hidden'){if(state.running&&!state.demo){setActivity('lifecycle','Keeping Trail Mesh session alive while the picker is open',5000);trace('info','Lifecycle','App backgrounded; verified session remains requested');}return;}if(!state.sessionRequested||state.demo||!plugin())return;Promise.resolve(requirePlugin().getStatus()).then(function(s){if(s&&s.running){state.running=true;render();return;}trace('warn','Lifecycle','Android paused the radio session; resuming with remembered consent');return requirePlugin().start({displayName:safeName()}).then(function(){state.running=true;trace('ok','Lifecycle','Trail Mesh session resumed after returning to the app');render();}).catch(function(e){trace('error','Lifecycle','Could not resume Trail Mesh: '+(e.message||'radio unavailable'));render();});}).catch(function(e){trace('error','Lifecycle','Could not read radio status after returning: '+(e.message||'unavailable'));});});}

  window.RWTrailMesh = { isAvailable:function(){return Boolean(plugin());}, open:open, close:close, start:start, stop:stop, send:function(message,endpointId){return requirePlugin().sendMessage({message:message,endpointId:endpointId||null});}, sendChat:sendChat, status:function(){return requirePlugin().getStatus();} };
  window.RWNearbyMesh = window.RWTrailMesh;
  function boot(){if(!plugin())return;loadTrace();loadUiState();trace('ok','Boot','Native Trail Mesh bridge loaded');window.addEventListener('error',function(e){trace('error','UI',e.message||'Unknown JavaScript error');});window.addEventListener('unhandledrejection',function(e){trace('error','Promise',(e.reason&&e.reason.message)||String(e.reason||'Unhandled operation failure'));});installEntryPoints();installBridges();installLifecycleGuard();new MutationObserver(function(){installEntryPoints();installBridges();}).observe(document.body,{childList:true,subtree:true});}
